    search_str text := $2;
    occurrence integer := $3;
    pos integer := 1;
    found_count integer := 0;
    search_len integer := length(search_str);
BEGIN
    WHILE pos <= length(main_str) - search_len + 1 AND found_count < occurrence LOOP
        IF substring(main_str FROM pos FOR search_len) = search_str THEN
            found_count := found_count + 1;
            IF found_count = occurrence THEN
